"""Adversarial differential fuzzing: tiny caps, constant sampling, repartitions."""
import json
import random
import sys

sys.path.insert(0, '/workspace/submission')
sys.path.insert(0, '/workspace/tests')

from utils import run_request as fast
from reference import Ref


def borders(rng, U, maxr):
    n = rng.randint(1, min(maxr, max(1, U - 1)))
    pts = sorted(rng.sample(range(1, U), n)) if U > 1 and n else []
    return [0] + pts + [U]


def make_run(rng):
    M = rng.randint(1, 5)
    L = rng.randint(1, 4)
    U = rng.choice([1, 2, 3, 12, 60])
    kind = rng.choice(['fifo', 'sp', 'sff', 'wfq'])
    flows = rng.sample(range(0, 20), rng.randint(1, 6))
    if kind == 'sp':
        policy = {'kind': 'sp', 'levels': [[f, rng.randint(0, U + 3)] for f in flows]}
    elif kind == 'wfq':
        policy = {'kind': 'wfq', 'weights': [[f, rng.randint(1, 16)] for f in flows]}
    else:
        policy = {'kind': kind}
    events = []
    ids = rng.sample(range(0, 400), rng.randint(10, 90))
    saves = []
    seen = []
    for _ in range(rng.randint(40, 140)):
        c = rng.random()
        if c < 0.34 and ids:
            pid = ids.pop()
            events.append(['enqueue', pid, rng.choice(flows), rng.randint(1, 9), rng.randint(0, U + 3)])
            seen.append(pid)
        elif c < 0.52:
            events.append(['dequeue', rng.randint(1, 5)])
        elif c < 0.60:
            events.append(['sample'])
        elif c < 0.72:
            events.append(['repartition', borders(rng, U, 9)])
        elif c < 0.80 and seen:
            events.append(['cancel', rng.choice(seen)])
        elif c < 0.85 and seen:
            events.append(['inspect', rng.choice(seen)])
        elif c < 0.87 and kind == 'wfq':
            events.append(['weight', rng.choice(flows), rng.randint(1, 32)])
        elif c < 0.94:
            name = rng.randint(0, 4)
            events.append(['save', name])
            saves.append(name)
        elif saves:
            events.append(['restore', rng.choice(saves)])
        else:
            events.append(['save', 0])
            saves.append(0)
    return {'banks': M, 'load_balancers': L,
            'fifo_bytes': rng.choice([1, 2, 5, 9, 20]),
            'pifo_bytes': rng.choice([1, 2, 5, 9, 20]),
            'refill_batch': rng.randint(1, 6),
            'sample_period': rng.choice([1, 1, 2, 3]),
            'borders': borders(rng, U, 9), 'policy': policy, 'events': events}


def main():
    cases = int(sys.argv[1]) if len(sys.argv) > 1 else 40
    seed = int(sys.argv[2]) if len(sys.argv) > 2 else 1
    rng = random.Random(seed)
    bad = 0
    for case in range(cases):
        runs = [make_run(rng) for _ in range(rng.randint(1, 3))]
        request = {'runs': runs}
        expected = {'runs': [Ref(cfg).run(cfg['events']) for cfg in runs]}
        actual = fast(json.loads(json.dumps(request)))
        if actual != expected:
            bad += 1
            print('MISMATCH case', case)
            for k, (a, e) in enumerate(zip(actual['runs'], expected['runs'])):
                if a == e:
                    continue
                print(' run', k)
                for x, y in zip(a['log'], e['log']):
                    if x != y:
                        print('  first log diff\n   got', x, '\n   exp', y)
                        break
                else:
                    print('  log length', len(a['log']), len(e['log']))
                for key in e['state']:
                    if a['state'].get(key) != e['state'][key]:
                        print('  state diff', key, '\n   got', a['state'].get(key), '\n   exp', e['state'][key])
            with open('/workspace/tests/fail3_%d_%d.json' % (seed, case), 'w') as fh:
                json.dump(request, fh, indent=1)
            if bad >= 2:
                break
    print('adversarial: checked %d cases, %d mismatches' % (case + 1, bad))
    return 1 if bad else 0


if __name__ == '__main__':
    sys.exit(main())
